def find_index_to_delete(n, b):
    def is_arithmetic(lst):
        if len(lst) <= 1:
            return True
        diff = lst[1] - lst[0]
        for i in range(1, len(lst)):
            if lst[i] - lst[i-1] != diff:
                return False
        return True

    count = [0] * (2 * 10**9 + 2)
    for x in b:
        count[x + 10**9 + 1] += 1

    for i in range(n):
        target_diff = None
        valid = True
        used_count = [0] * (2 * 10**9 + 2)
        for j in range(n):
            if j == i:
                continue
            val = b[j] + 10**9 + 1
            if target_diff is None:
                target_diff = val - used_count[val]
            elif val - used_count[val] != target_diff:
                valid = False
                break
            used_count[val] += 1

        if valid:
            return i + 1

    return -1

