def find_arithmetic_progression_index(n, b):
    sorted_b = sorted(b)
    differences = {}

    # Calculate all possible differences between consecutive elements
    for i in range(1, len(sorted_b)):
        diff = sorted_b[i] - sorted_b[i - 1]
        if diff not in differences:
            differences[diff] = []
        differences[diff].append((sorted_b[i], sorted_b[i - 1]))

    for j in range(n):
        candidate_diffs = set()

        # Check if deleting b[j] results in an arithmetic progression
        for diff, pairs in differences.items():
            valid = True
            for x, y in pairs:
                if x != b[j] and y != b[j]:
                    if x < y:
                        if y - x != diff:
                            valid = False
                            break
                    else:
                        if x - y != diff:
                            valid = False
                            break
            if valid:
                candidate_diffs.add(diff)

        # If we found a valid difference set after removing b[j], return j
        if len(candidate_diffs) == 1:
            return j + 1

    # If no valid index was found, return -1
    return -1

